package financeos.vk;
import java.awt.*;
import java.awt.image.BufferedImage;
import java.io.*;
import java.util.*;
import java.util.List;
import javax.imageio.ImageIO;
/** Images are under our control. Native VK bubbles and button geometry are not. */
public final class NightAtlas {
    public static void background(Graphics2D g,int width,int height){g.setPaint(new GradientPaint(width,0,new Color(27,41,64),0,height,new Color(14,20,32)));g.fillRect(0,0,width,height);}
    public static byte[] wallpaper(){try(var in=NightAtlas.class.getResourceAsStream("/financeos/night-atlas.jpg")){if(in==null)throw new IllegalStateException("Wallpaper resource missing");var image=ImageIO.read(in);if(image==null)throw new IOException("Invalid wallpaper");return encode(image);}catch(IOException e){throw new IllegalStateException("Wallpaper unavailable",e);}}
    public static byte[] summary(String report,boolean dark){var image=new BufferedImage(1100,480,BufferedImage.TYPE_INT_RGB);var g=image.createGraphics();try{g.setRenderingHint(RenderingHints.KEY_ANTIALIASING,RenderingHints.VALUE_ANTIALIAS_ON);if(dark)background(g,1100,480);else{g.setColor(new Color(244,247,252));g.fillRect(0,0,1100,480);}g.setColor(dark?new Color(180,197,232):new Color(55,76,109));g.setFont(new Font("SansSerif",Font.PLAIN,21));g.drawString("FINANCEOS · НОЧНОЙ АТЛАС",50,55);int y=115;for(String label:List.of("Свободные деньги","Фактический баланс","Осталось оплатить по плану","Осталось по плану")){String line=report.lines().filter(s->s.startsWith(label+" ·")).findFirst().orElse("");if(line.isBlank())continue;g.setColor(dark?new Color(237,241,248):new Color(25,42,65));g.setFont(new Font("SansSerif",label.equals("Свободные деньги")?Font.BOLD:Font.PLAIN,label.equals("Свободные деньги")?34:25));g.drawString(ChartRenderer.fit(line,g.getFontMetrics(),1000),50,y);y+=75;}g.setFont(new Font("SansSerif",Font.PLAIN,20));g.setColor(dark?new Color(176,189,208):new Color(73,93,120));g.drawString("Свободные деньги · баланс минус остаток плана",50,435);return encode(image);}finally{g.dispose();}}
    public static byte[] bubbles(){var image=new BufferedImage(900,540,BufferedImage.TYPE_INT_RGB);var g=image.createGraphics();try{background(g,900,540);g.setRenderingHint(RenderingHints.KEY_ANTIALIASING,RenderingHints.VALUE_ANTIALIAS_ON);g.setColor(new Color(23,36,58));g.fillRoundRect(45,60,680,170,28,28);g.setColor(new Color(179,202,231));g.setFont(new Font("SansSerif",Font.PLAIN,22));g.drawString("finance-bot",75,105);g.setColor(new Color(237,241,248));g.setFont(new Font("SansSerif",Font.PLAIN,28));g.drawString("Ночной атлас · пример сообщения",75,165);g.setColor(new Color(42,62,91));g.fillRoundRect(230,270,620,120,28,28);g.setColor(new Color(237,241,248));g.drawString("Моё сообщение",260,340);g.setFont(new Font("SansSerif",Font.PLAIN,20));g.setColor(new Color(180,197,232));g.drawString("Образец · стиль сообщений выбирается вручную в VK",45,475);return encode(image);}finally{g.dispose();}}
    private static byte[] encode(BufferedImage image){try{var out=new ByteArrayOutputStream();ImageIO.write(image,"png",out);return out.toByteArray();}catch(IOException e){throw new IllegalStateException(e);}}
}
